#!/usr/bin/env bash
# Adds the remote start/stop/restart command channel to the Agent. The
# Admin Panel's app/blueprints/agent_api.py (get_pending_command/ack_command,
# /api/v1/instances/commands) already existed and the Start/Stop/Restart
# buttons in app/blueprints/instances.py (_queue_command) already queued
# rows into InstanceCommand - but nothing on the Agent side ever polled for
# them. Every click just sat in the DB as "pending" forever.
#
# Adds agent/commands.py (poll -> execute against ProcessSupervisor -> ack
# success/failed), two new ApiClient methods (get_pending_command,
# ack_command), a command-poll thread wired into agent/main.py, and a "run"
# subcommand on service_files/windows/opslab_agent_service.py for
# console/no-install use.
#
# Updates BOTH this repo's own ./agent + ./service_files (what
# build_msi_selfcontained.sh / build_msi.sh / the exe builder stage from
# directly) AND the served app/static/installers/opslab-agent.tar.gz (what
# install.ps1 downloads for a fresh enrollment) - so the two can't drift
# apart the way earlier fix_*.sh scripts risked by only touching the
# tarball.
#
# Verified importable/compiling on Linux; the Windows service framework
# bits (win32serviceutil.HandleCommandLine) carry the same untested-on-
# real-Windows caveat already on record for that file - only the new "run"
# branch is exercised here since this build environment has no Windows box.
#
# Run from inside /root/admin_panel (or wherever this repo lives on the VPS).
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> [1/3] Extracting fixed agent/ + service_files/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'B64_EOF_MARKER'

B64_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if [ ! -f "$TMP_EXTRACT/agent/commands.py" ]; then
    echo "    ERROR: fix not found in the extracted payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
cp -f "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py" service_files/windows/opslab_agent_service.py
echo "    Updated agent/*.py and service_files/windows/opslab_agent_service.py in this repo."

echo "==> [2/3] Rewriting app/static/installers/opslab-agent.tar.gz"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> [3/3] Verifying the served tarball"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
VERIFY_DIR="$(mktemp -d)"
tar -xzf app/static/installers/opslab-agent.tar.gz -C "$VERIFY_DIR"
if [ -f "$VERIFY_DIR/agent/commands.py" ]; then
    echo "    Confirmed: agent/commands.py is present in the packaged tarball."
else
    echo "    ERROR: fix not found in the packaged tarball!"
    rm -rf "$VERIFY_DIR"
    exit 1
fi
rm -rf "$VERIFY_DIR"

echo ""
echo "Done. Restart the app the same way as before:"
echo "    pkill -f 'admin_panel/run.py'"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > /root/admin_panel/app.log 2>&1 &"
echo ""
echo "New enrollments (irm .../install.ps1 -OutFile install.ps1; .\install.ps1 -Token ... -AdminUrl ...)"
echo "now download this fixed tarball automatically - nothing else to change on that side."
echo ""
echo "Already-enrolled instances: their running service still has the old code until"
echo "it self-updates or is reinstalled via Releases/Rollouts - this only lands on"
echo "FUTURE enrollments and future MSI/exe builds from this repo."
